    for t in seq(0, tmax):

        # 1) Update boundary condition on ey at i = 0.
        for j in seq(0, ny):
            ey[0, j] = _fict_[t]

        # 2) Update interior of ey using hz from previous time step.
        for i in seq(1, nx):
            for j in seq(0, ny):
